mapper.sql:
WITH scoped_achievement AS ( SELECT achievement.id, COALESCE(JSON_UNQUOTE(type_override.field_value), achievement.achievement_type) AS achievement_type, YEAR(COALESCE( STR_TO_DATE(JSON_UNQUOTE(date_override.field_value), '%Y-%m-%d'), achievement.publication_date)) AS publication_year, achievement.updated_at FROM achievement LEFT JOIN canonical_entity_link member_link ON member_link.entity_type = 'ACHIEVEMENT' AND member_link.entity_id = achievement.id LEFT JOIN manual_field_override type_override ON type_override.achievement_id = achievement.id AND type_override.field_name = 'type' AND type_override.active = TRUE LEFT JOIN manual_field_override date_override ON date_override.achievement_id = achievement.id AND date_override.field_name = 'publicationDate' AND date_override.active = TRUE WHERE member_link.entity_id IS NULL
AND YEAR(COALESCE( STR_TO_DATE(JSON_UNQUOTE(date_override.field_value), '%Y-%m-%d'), achievement.publication_date)) >= #{query.publicationYearFrom}
AND YEAR(COALESCE( STR_TO_DATE(JSON_UNQUOTE(date_override.field_value), '%Y-%m-%d'), achievement.publication_date)) <= #{query.publicationYearTo}
AND COALESCE(JSON_UNQUOTE(type_override.field_value), achievement.achievement_type) = #{query.achievementType}
AND EXISTS ( SELECT 1 FROM achievement_source source_relation JOIN data_source source_value ON source_value.id = source_relation.source_id LEFT JOIN canonical_entity_link source_achievement_link ON source_achievement_link.entity_type = 'ACHIEVEMENT' AND source_achievement_link.entity_id = source_relation.achievement_id WHERE COALESCE( source_achievement_link.canonical_entity_id, source_relation.achievement_id) = achievement.id AND source_value.source_type = #{query.sourceType} )
AND EXISTS ( SELECT 1 FROM authorship_organization organization_relation LEFT JOIN canonical_entity_link organization_achievement_link ON organization_achievement_link.entity_type = 'ACHIEVEMENT' AND organization_achievement_link.entity_id = organization_relation.achievement_id LEFT JOIN canonical_entity_link organization_link ON organization_link.entity_type = 'ORGANIZATION' AND organization_link.entity_id = organization_relation.organization_id WHERE COALESCE( organization_achievement_link.canonical_entity_id, organization_relation.achievement_id) = achievement.id AND COALESCE( organization_link.canonical_entity_id, organization_relation.organization_id) = #{query.organizationId} )
AND EXISTS ( SELECT 1 FROM achievement_subject topic_relation LEFT JOIN canonical_entity_link topic_achievement_link ON topic_achievement_link.entity_type = 'ACHIEVEMENT' AND topic_achievement_link.entity_id = topic_relation.achievement_id WHERE COALESCE( topic_achievement_link.canonical_entity_id, topic_relation.achievement_id) = achievement.id AND topic_relation.subject_id = #{query.topicId} )
)
